// AI: below section was generated by an AI
enum FirmwarePeerProtocol : uint8_t {
  FirmwarePeerUnknown = 0,
  FirmwarePeerLegacy,
  FirmwarePeerTargetable,
};

enum FirmwarePropagationState : uint8_t {
  FirmwarePropagationIdle = 0,
  FirmwarePropagationLooking,
  FirmwarePropagationTransferring,
  FirmwarePropagationAwaitingHealth,
  FirmwarePropagationExpired,
  FirmwarePropagationFailed,
};

enum FirmwareBootMarker : uint8_t {
  FirmwareBootMarkerNone = 0,
  FirmwareBootMarkerPending,
  FirmwareBootMarkerConsumed,
};

enum FirmwareBootAction : uint8_t {
  FirmwareBootNoPropagation = 0,
  FirmwareBootStartPropagation,
};

struct FirmwareUpdatedBootMarker {
  FirmwareBootMarker state = FirmwareBootMarkerNone;
  FirmwareImageArtifact artifact;
};

inline FirmwareUpdatedBootMarker firmwareUpdatedBootMarkerFor(
    const FirmwareImageArtifact& artifact
) {
  FirmwareUpdatedBootMarker marker;
  if (!firmwareArtifactMatchesCanonical(artifact)) return marker;
  marker.state = FirmwareBootMarkerPending;
  marker.artifact = artifact;
  return marker;
}

// Models the durable marker owned by the eventual receiver integration. The
// caller must persist marker() before allowing an ordinary reboot.
class FirmwareUpdatedBootLatch {
public:
  explicit FirmwareUpdatedBootLatch(FirmwareUpdatedBootMarker marker) : _marker(marker) {}

  FirmwareBootAction consumeSuccessfulUpdateBoot(
      const FirmwareImageArtifact& runningArtifact,
      bool healthy
  ) {
    if (_marker.state != FirmwareBootMarkerPending || !healthy
        || !firmwareArtifactMatchesCanonical(runningArtifact)
        || !firmwareArtifactsHaveSameIdentity(runningArtifact, _marker.artifact))
      return FirmwareBootNoPropagation;
    _marker.state = FirmwareBootMarkerConsumed;
    return FirmwareBootStartPropagation;
  }

  FirmwareUpdatedBootMarker marker() const { return _marker; }

private:
  FirmwareUpdatedBootMarker _marker;
};
// AI: end

