// Holds only volatile post-migration propagation state. Transport and wire
// ownership remain outside this type until the canonical targetable protocol
// defines their packet/action IDs.
class FirmwarePropagationBaton {
public:
  static constexpr uint32_t IdleWindowSeconds = 60;

  bool start(const uint8_t senderMac[6], const FirmwareImageArtifact& artifact, uint32_t now) {
    if (_state != FirmwarePropagationIdle || !macIsKnown(senderMac)
        || !firmwareArtifactMatchesCanonical(artifact)
        || artifact.artifactId != CanonicalArtifactDig2goV14OtaApplication)
      return false;
    memcpy(_senderMac, senderMac, sizeof(_senderMac));
    _artifact = artifact;
    _idleDeadline = now + IdleWindowSeconds;
    _state = FirmwarePropagationLooking;
    return true;
  }

  bool selectReceiver(
      const uint8_t receiverMac[6],
      FirmwarePeerProtocol protocol,
      uint32_t sessionNonce,
      uint32_t now
  ) {
    if (_state != FirmwarePropagationLooking || protocol != FirmwarePeerTargetable
        || !macIsKnown(receiverMac) || macEquals(receiverMac, _senderMac)
        || sessionNonce == 0 || deadlineReached(now))
      return false;
    memcpy(_receiverMac, receiverMac, sizeof(_receiverMac));
    _transferredBytes = 0;
    _retryUsed = false;
    _sessionNonce = sessionNonce;
    _state = FirmwarePropagationTransferring;
    return true;
  }

  bool recordProgress(const uint8_t receiverMac[6], size_t transferredBytes) {
    if (_state != FirmwarePropagationTransferring || !receiverIs(receiverMac)
        || transferredBytes < _transferredBytes
        || transferredBytes > _artifact.imageLengthBytes)
      return false;
    _transferredBytes = transferredBytes;
    return true;
  }

  bool retryFromZero(const uint8_t receiverMac[6]) {
    if (_state != FirmwarePropagationTransferring || !receiverIs(receiverMac) || _retryUsed)
      return false;
    _retryUsed = true;
    _transferredBytes = 0;
    return true;
  }

  bool awaitHealth(const uint8_t receiverMac[6]) {
    if (_state != FirmwarePropagationTransferring || !receiverIs(receiverMac)
        || _transferredBytes != _artifact.imageLengthBytes)
      return false;
    _state = FirmwarePropagationAwaitingHealth;
    return true;
  }

  bool refreshActivity(uint32_t now) {
    if (_state != FirmwarePropagationLooking
        && _state != FirmwarePropagationTransferring
        && _state != FirmwarePropagationAwaitingHealth)
      return false;
    _idleDeadline = now + IdleWindowSeconds;
    return true;
  }

  bool handoffFromCompletionProof(
      const FirmwareUpdateCompletionProof& proof,
      uint32_t now
  ) {
    if (_state != FirmwarePropagationAwaitingHealth || !proof.isComplete()
        || !proof.targetIs(_receiverMac)
        || proof.sessionNonce() != _sessionNonce
        || !firmwareArtifactMatchesCanonical(proof.artifact())
        || !firmwareArtifactsHaveSameIdentity(proof.artifact(), _artifact))
      return false;
    memcpy(_senderMac, _receiverMac, sizeof(_senderMac));
    memset(_receiverMac, 0, sizeof(_receiverMac));
    _transferredBytes = 0;
    _sessionNonce = 0;
    _handedOff = true;
    _idleDeadline = now + IdleWindowSeconds;
    _state = FirmwarePropagationLooking;
    return true;
  }

  bool expireIfIdle(uint32_t now) {
    if ((_state != FirmwarePropagationLooking
        && _state != FirmwarePropagationTransferring
        && _state != FirmwarePropagationAwaitingHealth)
        || !deadlineReached(now))
      return false;
    _state = FirmwarePropagationExpired;
    return true;
  }

  FirmwarePropagationState state() const { return _state; }
  CanonicalArtifactId artifactId() const { return _artifact.artifactId; }
  size_t transferredBytes() const { return _transferredBytes; }
  bool senderIs(const uint8_t mac[6]) const { return macEquals(mac, _senderMac); }
  bool receiverIs(const uint8_t mac[6]) const { return macEquals(mac, _receiverMac); }
  bool batonHandedOff() const { return _handedOff; }
  bool fleetIsCurrent() const { return false; }

private:
  static bool macIsKnown(const uint8_t mac[6]) {
    if (!mac) return false;
    uint8_t combined = 0;
    for (size_t index = 0; index < 6; index++) combined |= mac[index];
    return combined != 0;
  }

  static bool macEquals(const uint8_t left[6], const uint8_t right[6]) {
    return left && right && memcmp(left, right, 6) == 0;
  }

  bool deadlineReached(uint32_t now) const {
    return static_cast<int32_t>(now - _idleDeadline) >= 0;
  }

  uint8_t _senderMac[6] = {0};
  uint8_t _receiverMac[6] = {0};
  FirmwareImageArtifact _artifact;
  uint32_t _idleDeadline = 0;
  size_t _transferredBytes = 0;
  uint32_t _sessionNonce = 0;
  FirmwarePropagationState _state = FirmwarePropagationIdle;
  bool _retryUsed = false;
  bool _handedOff = false;
};
